// @ts-nocheck
// Hairline figure "lockers" for max-harrow-skyfall-4p. Generated by the murder-mystery-story-tree skill via hairline-create.
// Body is the figure file verbatim; edit with: python scripts/art.py unwrap <this> lockers.js → look.mjs → wrap.
export default function define(HL, hairline) {
/**
 * Lockers: a bank of four gear lockers, a rig hanging in each. The locker
 * under the pointer swings its door wide; its neighbours open a little,
 * staggered outwards from it on the 700ms curve. One rig has no reserve: a
 * bare cord and its flap hanging open. At rest that locker's door is ajar.
 * Each door counts itself in dots. The slider is the stagger, in ms.
 *
 * The pattern: discrete items. Tweens, a stagger by distance, identity carried
 * by geometry, and a hit test on static bands along the closed fronts, so a
 * door swinging out under the pointer cannot flip the choice.
 */
const {
  Cam, clamp, facing, fillet, fit, open, poly, prism, proj, rad, rings, rrect, seg,
  tdone, tset, tval, tween, disposer, mk, place, pointer, put, register, solid,
} = HL;

const NB = 4, PW = 36, D = 30, H = 100, EMPTY = 2;
const W = PW - 6, Z0 = 5, Z1 = H - 5, YR = D - 4, TK = 0.9;
const OPEN = 100, AJAR = 22, FALL = [1, 0.3, 0.12, 0.05];
const NAMES = ["first locker", "second locker", "the empty one", "fourth locker"];
const DOOR = fillet([[0, Z0], [W, Z0], [W, Z1], [0, Z1]], [3, 3, 3, 3]);
const restAngle = (i) => (i === EMPTY ? AJAR : 0);

/**
 * The rig hanging in bay i, as [d, class, face] triples: a pack, a reserve above it, straps, the cord and its hook.
 * The empty bay's rig has no reserve: a longer bare cord, and the reserve's flap hanging askew off the pack.
 * Kept narrow and near the front so, seen through the opening, it never crosses the frame.
 */
function rig(P, i) {
  const x0 = i * PW + 3, at = (x, z, dy = 0) => P(x0 + x, YR + dy, z);
  const plate = (r) => [[poly(r.map((q) => at(q.u, q.v, -1.6))), "lo"], [poly(r.map((q) => at(q.u, q.v))), "", true]];
  const empty = i === EMPTY, top = empty ? 60 : 74, m = 12;
  const out = [...plate(rrect(4, 28, 20, 60, 4, 4))];
  if (empty) {
    // the flap, a plate turned 32 degrees about the pack's top right corner, hanging open
    const c = Math.cos(rad(-32)), s = Math.sin(rad(-32));
    const flap = fillet([[-14, 0], [0, 0], [0, -10], [-14, -10]], [1, 1, 2.5, 2.5]).map(([u, v]) => [18 + u * c - v * s, 59 + u * s + v * c]);
    out.push([poly(flap.map(([x, z]) => at(x, z, 2))), "", true]);
  } else out.push(...plate(rrect(5.5, 62, 18.5, 74, 3, 4)));
  out.push(
    [[[7, 28, 6, 15, 8.5, 11.5], [17, 28, 18, 15, 15.5, 11.5]].map((q) => open([at(q[0], q[1]), at(q[2], q[3]), at(q[4], q[5])])).join(""), "nf lo"],
    [open([at(m, top), at(m, 88), at(m, 91, -1), at(m + 2, 92.5, -1.5), at(m + 3.5, 91, -1.5)]), "nf"],
  );
  return out;
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let stag = value;

  // Fitted with the first door swung wide, the farthest any part reaches.
  const C = Cam(45, 0.5, 1.72);
  fit(C, [[0, 0, 0], [NB * PW, D, 0], [NB * PW, 0, 0], [0, D, 0], [0, 0, H], [NB * PW, 0, H], [-3, D + 31, 0], [-3, D + 31, H]], 200, 166);
  const P = proj(C), front = facing(C);

  const g = mk("g", {}, svg);
  const [br, bi] = rings(0, 0, NB * PW, D, 4, 1.6);
  put(solid(g), prism(P, front, br, bi, 0, H));

  // Bay by bay, left to right: frame, rig, then the door that closes over them.
  const doors = [];
  for (let i = 0; i < NB; i++) {
    const x0 = i * PW + 3;
    mk("path", { d: poly(DOOR.map(([x, z]) => P(x0 + x, D, z))), class: "nf lo" }, g);
    const parts = rig(P, i).map(([d, cls, face]) => [mk("path", { d, class: cls }, g), face]);
    const contents = parts.filter((q) => q[1]).map((q) => q[0]);
    const dg = mk("g", {}, g);
    const back = mk("path", { class: "lo" }, dg), face = mk("path", {}, dg);
    const vents = mk("path", { class: "nf lo" }, dg), handle = mk("path", { class: "nf" }, dg);
    const dots = [];
    for (let k = 0; k <= i; k++) dots.push(mk("circle", { r: 1, class: "dot off" }, dg));
    doors.push({ x0, back, face, vents, handle, dots, contents, tw: tween(restAngle(i)), drawn: NaN });
  }
  doors[EMPTY].face.classList.add("hi");

  /** Door i swung th degrees about its left edge. Past 45° its inside faces us, so the two outlines trade places and the outside's marks go. */
  function draw(i, th) {
    const d = doors[i];
    if (th === d.drawn) return;
    d.drawn = th;
    const c = Math.cos(rad(th)), s = Math.sin(rad(th)), inside = th > 45, f = inside ? 1 : -1;
    const at = (u, z, t) => P(d.x0 + u * c + t * s, D + u * s - t * c, z);
    d.back.setAttribute("d", poly(DOOR.map(([u, z]) => at(u, z, -f * TK))));
    d.face.setAttribute("d", poly(DOOR.map(([u, z]) => at(u, z, f * TK))));
    d.vents.setAttribute("d", inside ? "" : [Z1 - 9, Z1 - 12.5, Z1 - 16].map((z) => seg(at(8, z, -TK), at(W - 8, z, -TK))).join(""));
    d.handle.setAttribute("d", inside ? "" : seg(at(W - 4.5, H / 2 - 7, -TK), at(W - 4.5, H / 2 + 7, -TK)));
    d.dots.forEach((el, k) => { el.setAttribute("r", inside ? 0 : 1); place(el, at(W / 2 + (k - i / 2) * 2.8, Z1 - 4.5, -TK)); });
  }

  const B = register(stage, (_dt, now) => {
    let moving = false;
    doors.forEach((d, i) => { draw(i, tval(d.tw, now)); if (!tdone(d.tw, now)) moving = true; });
    return moving;
  });
  bag.add(B.unregister);

  // Hit bands: the closed fronts, bay by bay, in the bay's own (s, r) coordinates. They never move.
  const o = P(0, 0, 0), c0 = P(3 + W / 2, D, H / 2), c1 = P(PW + 3 + W / 2, D, H / 2), z1 = P(0, 0, 1);
  const dv = [c1[0] - c0[0], c1[1] - c0[1]], ez = [z1[0] - o[0], z1[1] - o[1]];
  const det = dv[0] * ez[1] - dv[1] * ez[0];
  function hit([x, y]) {
    const qx = x - c0[0], qy = y - c0[1];
    const s = (qx * ez[1] - qy * ez[0]) / det, r = (dv[0] * qy - dv[1] * qx) / det;
    if (Math.abs(r) > H / 2 + 2 || s < -0.5 || s > NB - 0.5) return -1;
    return clamp(Math.round(s), 0, NB - 1);
  }

  let act = -1;
  /** Opens locker a (-1 puts them all back). The stagger spreads out from the one opened, or the one let go. */
  function setActive(a) {
    if (a === act) return;
    const now = performance.now(), from = a >= 0 ? a : act;
    act = a;
    doors.forEach((d, i) => {
      const th = a < 0 ? restAngle(i) : Math.max(OPEN * FALL[Math.abs(i - a)], restAngle(i));
      tset(d.tw, th, now, Math.abs(i - from) * stag);
      // At rest the ajar door is bright; once a locker is opened, the bright goes to what hangs inside it.
      d.face.classList.toggle("hi", a < 0 && i === EMPTY);
      d.contents.forEach((el) => el.classList.toggle("hi", i === a));
    });
    read.textContent = a < 0 ? "rest" : NAMES[a];
    B.wake();
  }

  bag.add(pointer(stage, { move: (p) => setActive(hit(p)), leave: () => setActive(-1) }));
  bag.add(() => svg.replaceChildren());

  return {
    set: (v) => { stag = v; },
    destroy: bag.dispose,
  };
}

hairline({
  name: "lockers",
  means: "Four gear lockers: the one under the pointer swings open, its neighbours after it, and one rig has no reserve.",
  rules: [1, 2, 5, 10],
  range: [20, 50, 90],
  tour: [[137, 142], [181, 164], [224, 186], null],
  mount,
});
}
